package com.bank.atleastonce;

import org.apache.kafka.clients.consumer.*;
import org.apache.kafka.common.serialization.StringDeserializer;
import java.math.BigDecimal;
import java.time.Duration;
import java.util.*;
import java.util.logging.*;

public class AtLeastOnceDemo {
    private static final Logger log = Logger.getLogger(AtLeastOnceDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        IdempotentLedger ledger = new IdempotentLedger();

        Properties c = new Properties();
        c.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, "broker1:9092");
        c.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());
        c.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());
        c.put(ConsumerConfig.GROUP_ID_CONFIG, "settlement-service");
        c.put(ConsumerConfig.ENABLE_AUTO_COMMIT_CONFIG, "false");   // key for at-least-once
        c.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, "earliest");

        try (Consumer<String, String> consumer = new KafkaConsumer<>(c)) {
            consumer.subscribe(List.of("transfer-events"));
            boolean crashSimulated = false;

            while (true) {
                ConsumerRecords<String, String> records = consumer.poll(Duration.ofSeconds(1));
                if (records.isEmpty()) continue;

                for (ConsumerRecord<String, String> rec : records) {
                    // transferId is the idempotency key, e.g. "TXF-00042"
                    String transferId = rec.key();
                    // Process FIRST (apply to ledger), idempotently.
                    boolean applied = ledger.applyTransfer(transferId, rec.value());
                    log.info(() -> (applied ? "Applied " : "Skipped duplicate ") + transferId);

                    // Simulate a crash AFTER processing but BEFORE commit, once.
                    if (!crashSimulated && "TXF-00042".equals(transferId)) {
                        crashSimulated = true;
                        log.severe("CRASH before commit! Offset NOT committed → batch will reprocess");
                        // In a real crash the JVM dies here; we 'return' to mimic restart.
                        return;
                    }
                }
                // Commit ONLY after the whole batch processed successfully.
                consumer.commitSync();
                log.info("Offsets committed after successful processing");
            }
        }
    }
}

