class IdempotentLedger {
    // In production this is a DB table / unique constraint on transfer_id.
    private final Set<String> processed = new HashSet<>();
    private final Map<String, BigDecimal> balances = new HashMap<>(Map.of(
        "SAV2001", new BigDecimal("1000000"),   // Rajesh
        "CUR3001", new BigDecimal("250000")));   // Priya

    // Returns true if newly applied, false if it was a duplicate (idempotent).
    boolean applyTransfer(String transferId, String json) {
        if (processed.contains(transferId)) return false;   // dedup: no double charge
        // parse "SAV2001:CUR3001:50000"
        String[] parts = json.split(":");
        String from = parts[0], to = parts[1];
        BigDecimal amount = new BigDecimal(parts[2]);
        balances.merge(from, amount.negate(), BigDecimal::add);
        balances.merge(to, amount, BigDecimal::add);
        processed.add(transferId);
        return true;
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
